41	#include "mlir/Pass/Pass.h"
42	
43	#include "llvm/Support/Debug.h"
44	
45	using namespace mlir;
46	using namespace triton;
47	
48	static constexpr const char *DEBUG_TYPE = "MarkGMLoad";
49	#define LOG_DEBUG(...)                                                         \
50	  LLVM_DEBUG(llvm::dbgs() << " [" << DEBUG_TYPE << "] " << __VA_ARGS__ << "\n")
51	
52	namespace {
53	
54	static constexpr int kDefaultVBufferCount = 1;
55	static constexpr int kDefaultCBufferCount = 1;
56	
57	struct MarkCandidate {
58	  memref::CopyOp copyOp;
59	  memref::AllocOp destAlloc; // dest backing alloc after view-like piercing
60	  scope::ScopeOp scopeOp;    // nearest enclosing scope, should not be null
61	  int bufferCount;           // filled in Phase 2
62	};
63	
64	// Resolve whether a BlockArgument of func::FuncOp traces to a GM pointer.
65	// Returns:
66	//  - true if the arg belongs to the entry function (=> GM load source)
67	//  - false + non-null nextValue: trace through the caller's corresponding
68	//  operand, continue tracing
69	//  - false + null nextValue: tracing failed (no module / no caller)
70	static bool resolveFuncBlockArg(BlockArgument blockArg, func::FuncOp funcOp,
71	                                Value &nextValue) {
72	  auto moduleOp = funcOp->getParentOfType<ModuleOp>();
73	  if (!moduleOp) {
74	    LOG_DEBUG("[warning] moduleOp is null");
75	    return false;
76	  }
77	  if (SymbolTable::symbolKnownUseEmpty(funcOp.getNameAttr(), moduleOp)) {
78	    return true; // entry func argument => GM load
79	  }
80	  // Non-entry func: trace through callers.
81	  auto symbolUses = SymbolTable::getSymbolUses(funcOp.getNameAttr(), moduleOp);
82	  if (symbolUses && !symbolUses->empty()) {
83	    // get funcOp's caller, continue tracing
84	    auto callOp = cast<func::CallOp>((*symbolUses->begin()).getUser());
85	    nextValue = callOp.getOperands()[blockArg.getArgNumber()];
86	    return false;
87	  }
88	  LOG_DEBUG("[warning] Non-entry func: no caller uses "
89	            << funcOp.getNameAttr());
90	  return false;
91	}
92	
93	// Rule 1: Pierce view-like ops and trace scf.for / scf.while iter_args back to
94	// their init values. Returns true only when the terminal is a BlockArgument
95	// owned by the entry func::FuncOp (i.e. a GM pointer function argument).
96	static bool traceSourceToFuncArg(Value v) {
97	  while (true) {
98	    // 1. Pierce view-like ops and tensor.extract_slice.
99	    while (auto *defOp = v.getDefiningOp()) {
100	      if (auto viewLike = dyn_cast<ViewLikeOpInterface>(defOp)) {
101	        v = viewLike.getViewSource();
102	        continue;
103	      }
104	      if (auto extractSlice = dyn_cast<tensor::ExtractSliceOp>(defOp)) {
105	        v = extractSlice.getSource();
106	        continue;
107	      }
108	      break;
109	    }
110	    // 2. Check terminal: must be a BlockArgument.
111	    auto blockArg = dyn_cast<BlockArgument>(v);
112	    if (!blockArg) {
113	      return false; // ends at a defining op, not a GM arg
114	    }
115	    Operation *parentOp = blockArg.getOwner()->getParentOp();
116	
117	    if (auto funcOp = dyn_cast<func::FuncOp>(parentOp)) {
118	      Value nextV;
119	      if (resolveFuncBlockArg(blockArg, funcOp, nextV)) {
120	        return true; // find GM load source in funcOp arg
121	      }
122	      if (nextV) {
123	        v = nextV;
124	        continue;
125	      }
126	      return false;
127	    }
128	    if (auto forOp = dyn_cast<scf::ForOp>(parentOp)) {
129	      // iter_arg: trace its init value (skip induction var at index 0).
130	      v = forOp.getInitArgs()[blockArg.getArgNumber() - 1];
131	      continue;
132	    }
133	    if (auto whileOp = dyn_cast<scf::WhileOp>(parentOp)) {
134	      // before-block arg: trace to the corresponding init operand.
135	      if (blockArg.getOwner() == whileOp.getBeforeBody()) {
136	        v = whileOp.getInits()[blockArg.getArgNumber()];
137	        continue;
138	      }
139	      // after-block arg: trace to the corresponding condition operand.
140	      if (blockArg.getOwner() == whileOp.getAfterBody()) {
141	        auto condOp =
142	            cast<scf::ConditionOp>(whileOp.getBeforeBody()->getTerminator());
143	        v = condOp.getArgs()[blockArg.getArgNumber()];
144	        continue;
145	      }
146	      LOG_DEBUG("[warning] unsupport while op ");
147	      return false;
148	    }
149	    LOG_DEBUG("[warning] unsupport iterarg or control flow");
150	    return false; // other BlockArgument kinds
151	  }
152	}
153	
154	// Rule 2: Pierce view-like ops and tensor.extract_slice on the dest chain
155	// and return the backing memref::AllocOp, or null if the chain does not
156	// terminate at one.
157	static memref::AllocOp traceDestToAlloc(Value v) {
158	  while (auto *defOp = v.getDefiningOp()) {
159	    if (auto viewLikeOp = dyn_cast<ViewLikeOpInterface>(defOp)) {
160	      v = viewLikeOp.getViewSource();
161	      continue;
162	    }
163	    if (auto extractSliceOp = dyn_cast<tensor::ExtractSliceOp>(defOp)) {
164	      v = extractSliceOp.getSource();
165	      continue;
166	    }
167	    break;
168	  }
169	  return dyn_cast_or_null<memref::AllocOp>(v.getDefiningOp());
170	}
171	
172	// Rule 3: Resolve multi-buffer count N from the enclosing scope.
173	// Returns -1 when scopeOp is null or has an unexpected tcore_type,
174	// which should normally never happen.
175	static int resolveBufferCount(scope::ScopeOp scopeOp) {
176	  int buffer_num = -1;
177	  if (!scopeOp) {
178	    return buffer_num;
179	  }
180	  bool isCube = false;
181	  bool isVector = false;
182	  if (failed(triton::getScopeType(scopeOp, isCube, isVector))) {
183	    return buffer_num;
184	  }
185	  if (isVector) {
186	    buffer_num = kDefaultVBufferCount;
187	  } else if (isCube) {
188	    buffer_num = kDefaultCBufferCount;
189	  }
190	  LOG_DEBUG("return buffer num = " << buffer_num);
191	  return buffer_num;
192	}
193	
194	// Apply Rules 1 & 2 to a memref::CopyOp and build a MarkCandidate if eligible.
195	// Returns std::nullopt when any rule fails.
196	static std::optional<MarkCandidate> collectCandidate(memref::CopyOp copyOp) {
197	  // Rule 1: source must trace back to a func argument (GM load).
198	  if (!traceSourceToFuncArg(copyOp.getSource())) {
199	    return std::nullopt;
200	  }
201	  // Rule 2: dest must be created by a memref::AllocOp.
202	  auto allocOp = traceDestToAlloc(copyOp.getTarget());
203	  if (!allocOp) {
204	    LOG_DEBUG("dest not created by memref::AllocOp, skip");
205	    return std::nullopt;
206	  }
207	  auto scopeOp = copyOp->getParentOfType<scope::ScopeOp>();
208	  return MarkCandidate{copyOp, allocOp, scopeOp};
209	}
210	
211	// Phase 3: insert or update annotation::MarkOp with multi_buffer attr on the
212	// dest alloc. Returns false when bufferCount <= 1 (skip marking), true
213	// otherwise.
214	static bool markGMLoadCandidate(MarkCandidate &c) {
215	  if (c.bufferCount <= 1) {
216	    LOG_DEBUG("bufferCount <= 1, skip marking");
217	    return false;
218	  }
219	  // Check if an annotation::MarkOp already exists for this alloc.
220	  annotation::MarkOp existingMarkOp = nullptr;
221	  for (auto *user : c.destAlloc->getUsers()) {
222	    if (auto markOp = dyn_cast<annotation::MarkOp>(user)) {
223	      existingMarkOp = markOp;
224	      break;
225	    }
226	  }
227	  OpBuilder builder(c.destAlloc);
228	  if (existingMarkOp) {
229	    existingMarkOp->setAttr(hivm::MultiBufferAttr::name,
230	                            builder.getI32IntegerAttr(c.bufferCount));
231	  } else {
232	    builder.setInsertionPointAfter(c.destAlloc);
233	    auto markOp = builder.create<annotation::MarkOp>(c.destAlloc->getLoc(),
234	                                                     c.destAlloc.getResult());
235	    markOp->setAttr(hivm::MultiBufferAttr::name,
236	                    builder.getI32IntegerAttr(c.bufferCount));
237	  }
238	  LOG_DEBUG("marked multi_buffer = " << c.bufferCount << " on " << c.destAlloc);
239	  return true;
240	}
241	
242	} // namespace
243	
244	void MarkGMLoadPass::getDependentDialects(DialectRegistry &registry) const {
245	  registry.insert<annotation::AnnotationDialect, hivm::HIVMDialect,
246	                  memref::MemRefDialect, scope::ScopeDialect, scf::SCFDialect,
247	                  func::FuncDialect>();
248	}
249	
250	void MarkGMLoadPass::runOnOperation() {
251	  ModuleOp module = getOperation();
252	
253	  if (CVPipeline::hasFallbackAttr(module)) {
254	    return;
255	  }
256	
257	  LOG_DEBUG("Enter MarkGMLoad pass");
258	
259	  // Phase 1: collect candidates (read-only).
260	  SmallVector<MarkCandidate, 8> candidates;
261	  module.walk([&](memref::CopyOp copyOp) {
262	    if (auto candidate = collectCandidate(copyOp)) {
263	      candidates.push_back(*candidate);
264	    }
265	  });
266	
267	  if (candidates.empty()) {
268	    LOG_DEBUG("no GM load candidate found");
269	    return;
270	  }
271	
272	  // Phase 2 & 3: resolve buffer count N per candidate and insert
273	  // annotation::MarkOp (mutation).
274	  for (auto &c : candidates) {
275	    c.bufferCount = resolveBufferCount(c.scopeOp);
276	    if (c.bufferCount < 0) {
277	      LOG_DEBUG("resolveBufferCount failed for " << c.copyOp << ", fallback");
278	      CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
279	      return;
280	    }
281	    markGMLoadCandidate(c);
282	  }
283	
284	  LOG_DEBUG("after MarkGMLoad: " << module);
285	}
286	
287	namespace mlir {
288	namespace triton {
289	
290	std::unique_ptr<OperationPass<ModuleOp>> createMarkGMLoadPass() {
291	  return std::make_unique<MarkGMLoadPass>();
292	}
293	
294	} // namespace triton
295	} // namespace mlir
