418	// Process iterArg dependencies for all scf.for operations in the module.
419	// This function iterates through all for loops and checks each iterArg to
420	// determine if there are cross-core-type data dependencies.
421	void DataDependencyAnalysisPass::processIterArgDependencies() {
422	  auto &info = getAnalysis<DataDependencyInfo>();
423	
424	  // Step1: Collect all scf.for operations in the module
425	  llvm::SmallVector<scf::ForOp> forOps;
426	  module.walk([&](scf::ForOp forOp) { forOps.push_back(forOp); });
427	  LOG_DEBUG("Processing iterArg dependencies, found " << forOps.size()
428	                                                      << " scf.for ops\n");
429	
430	  // Step2: Process each iterArg of each scf.for operation
431	  for (scf::ForOp forOp : forOps) {
432	    size_t numIterArgs = forOp.getInitArgs().size();
433	    mlir::Operation *yieldOp = forOp.getBody()->getTerminator();
434	    if (!checkYieldCoreType(yieldOp)) {
435	      LOG_DEBUG("[ERROR]: Yield core type mismatch defining op\n");
436	      signalPassFailure();
437	    }
438	    for (int iterArgIndex = 0; iterArgIndex < numIterArgs; ++iterArgIndex) {
439	      mlir::Value initValue = forOp.getInits()[iterArgIndex];
440	      mlir::BlockArgument iterArg = forOp.getRegionIterArg(iterArgIndex);
441	      mlir::Value yieldedValue = forOp.getYieldedValues()[iterArgIndex];
442	      LOG_DEBUG("initValue" << initValue << "\n");
443	      LOG_DEBUG("yieldedValue" << yieldedValue << "\n");
444	
445	      if (!isValid1DValueForDependency(iterArg) &&
446	          (!isValidShapeForDependency(initValue) ||
447	           !isValidShapeForDependency(yieldedValue))) {
448	        LOG_DEBUG("iterarg: " << iterArg
449	                              << " is not valid tensor for dependency!");
450	        continue;
451	      }
452	
453	      Operation *initDefOp = initValue.getDefiningOp();
454	      Operation *yieldedDefOp = yieldedValue.getDefiningOp();
455	      if (!initDefOp) {
456	        LOG_DEBUG("warning: nested iterarg!");
457	        continue;
458	      }
459	      if (!yieldedDefOp) {
460	        continue;
461	      }
462	      if (isCubeOrVectorOp(initDefOp) && isCubeOrVectorOp(yieldedDefOp)) {
463	        continue;
464	      }
465	
466	      auto initDefResult = dyn_cast<mlir::OpResult>(initValue);
467	      auto initCoreType = getCoreTypeWithIndex(
468	          initDefOp, initDefResult ? initDefResult.getResultNumber() : 0);
469	      auto yieldCoreType = getCoreTypeWithIndex(forOp, iterArgIndex);
470	
471	      // Only process if init and yield have matching core types
472	      // Mismatch indicates a more complex dependency pattern that requires
473	      // special handling
474	      if (initCoreType != yieldCoreType) {
475	        if (!isValidValueForDependency(initValue)) {
476	          if (collectDiffCoreTypeUsers(iterArg, yieldCoreType).empty()) {
477	            continue;
478	          }
479	        }
480	        LOG_DEBUG("iterarg init core_type conflicts with yield");
481	        CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
482	        return;
483	      }
484	
485	      auto diffUsers = collectDiffCoreTypeUsers(iterArg, initCoreType);
486	      if (!diffUsers.empty()) {
487	        insertProducerAndRecordDeps(forOp, iterArg, initCoreType, diffUsers,
488	                                    info);
489	      }
490	    }
491	  }
492	}
493	
494	// Analyze V->C
495	void DataDependencyAnalysisPass::analyzeExternalInputs(
496	    DataDependencyInfo &info) {
497	  auto &blockInfoMap = info.getBlockInfoMap();
498	  auto &v2cDependencies = info.getV2CDependencies();
499	
500	  LOG_DEBUG("Analyzing external inputs for Cube blocks...\n");
501	  for (auto &[id, blockInfo] : blockInfoMap) {
502	    if (!blockInfo.isCube || blockInfo.isControl || blockInfo.inputs.empty())
503	      continue;
504	    LOG_DEBUG("Analyzing external inputs for Cube Block ID: " << id << "\n");
505	    for (mlir::Value input : blockInfo.inputs) {
506	      // Check if input is a value which can be produced by CUBE
507	      if (!isValidValueForDependency(input)) {
508	        LOG_DEBUG("Warning: [v->c] Input value is not a valid tensor for "
509	                  "dependency analysis.\n");
510	        continue;
511	      }
512	      // Check if input is a blockarg.
513	      if (isOuterOpArg(input)) {
514	        LOG_DEBUG("Warning: [v->c] Input value is a function/scf parameter.\n");
515	        continue;
516	      }
517	
518	      Operation *defOp = input.getDefiningOp();
519	      auto defReuslt = dyn_cast<mlir::OpResult>(input);
520	      auto coreType = getCoreTypeWithIndex(
521	          defOp, defReuslt ? defReuslt.getResultNumber() : 0);
522	      if (coreType == "") {
523	        LOG_DEBUG("Warning: [v->c] Input value has no core type attribute.\n");
524	        continue;
525	      }
526	
527	      // Case 1: Cube -> C->C special case
528	      if (coreType == ssbufferCoreTypeCubeAttr) {
529	        continue;
530	      }
531	      // Case 2: Vector -> V->C dependency
532	      if (coreType == ssbufferCoreTypeVectorAttr) {
533	        LOG_DEBUG("Found external input with VECTOR core type: " << input
534	                                                                 << "\n");
535	        auto producerIdOpt = CVPipeline::getOpBlockId(input.getDefiningOp());
536	        if (!producerIdOpt) {
537	          LOG_DEBUG(
538	              "Warning: [v->c] Producer block ID not found for input value.\n");
539	          continue;
540	        }
541	        int producerId = *producerIdOpt;
542	        collectDepInfo(input, DependencyType::VectorToCube, v2cDependencies,
543	                       producerId, blockInfo.blockId, info);
544	      }
545	    }
546	  }
547	  LOG_DEBUG("External input analysis complete.\n");
548	}
549	
550	// Analyze C->V
551	void DataDependencyAnalysisPass::analyzeExternalOutputs(
552	    DataDependencyInfo &info) {
553	  auto &blockInfoMap = info.getBlockInfoMap();
554	  auto &c2vDependencies = info.getC2VDependencies();
555	
556	  LOG_DEBUG("Analyzing external outputs for Cube blocks...\n");
557	  for (auto &[id, blockInfo] : blockInfoMap) {
558	    if (!blockInfo.isCube || blockInfo.outputs.empty())
559	      continue;
560	
561	    for (mlir::Value output : blockInfo.outputs) {
562	      // Check if output is a value which can be produced by CUBE
563	      if (!isValidValueForDependency(output)) {
564	        LOG_DEBUG("Warning: [c->v] Output value is not a valid tensor for "
565	                  "dependency analysis.\n");
566	        continue;
567	      }
568	      if (isa<mlir::IntegerType, mlir::FloatType>(output.getType())) {
569	        LOG_DEBUG("Warning: [c->v] Output value is a scalar, not a valid "
570	                  "tensor for dependency analysis.\n");
571	        continue;
572	      }
573	
574	      auto opResult = dyn_cast<OpResult>(output);
575	      unsigned resultIndex = opResult.getResultNumber();
576	      StringRef resultCoreType =
577	          getCoreTypeWithIndex(output.getDefiningOp(), resultIndex);
578	      if (resultCoreType != ssbufferCoreTypeCubeAttr) {
579	        continue;
580	      }
581	
582	      // Check who is using this output
583	      llvm::DenseSet<int> handledBlockIds;
584	
585	      // if c->v value will be transposed and then used by vector op, the value
586	      // can be transposed within fixpipe
587	      bool isAllTranspoesd = isAllTransposedInVector(output);
588	
589	      for (mlir::Operation *user : output.getUsers()) {
590	        int outputIndex = 0;
591	        if (isControlFlowOp(user)) {
592	          for (unsigned i = 0; i < user->getNumOperands(); ++i) {
593	            if (user->getOperand(i) == output) {
594	              outputIndex = i;
595	              break;
596	            }
597	          }
598	        }
599	        auto userCoreType = getCoreTypeWithIndex(user, outputIndex);
600	        if ((userCoreType == "")) {
601	          LOG_DEBUG(
602	              "Warning: [c->v] Input value has no core type attribute.\n");
603	          continue;
604	        }
605	        if (userCoreType == ssbufferCoreTypeVectorAttr) {
606	          LOG_DEBUG("Found external output used by VECTOR core type: " << output
607	                                                                       << "\n");
608	          auto consumerIdOpt = CVPipeline::getOpBlockId(user);
609	          if (!consumerIdOpt) {
610	            LOG_DEBUG("Warning: [c->v] Consumer block ID not found for user "
611	                      "operation.\n");
612	            continue;
613	          }
614	          int consumerId = *consumerIdOpt;
615	          auto inserted = handledBlockIds.insert(consumerId).second;
616	          if (inserted) {
617	            collectDepInfo(output, DependencyType::CubeToVector,
618	                           c2vDependencies, blockInfo.blockId, consumerId, info,
619	                           isAllTranspoesd);
620	          }
621	        }
622	        // If user belongs to Cube block, this C->C dependency was handled
623	        // in the Input analysis phase, so here we only handle C->V.
624	      }
625	    }
626	  }
627	  LOG_DEBUG("External output analysis complete.\n");
628	}
629	
630	void DataDependencyAnalysisPass::collectMemDepInfo(
631	    llvm::StringRef predCoreType, int producerBlockId, int consumerBlockId,
632	    int predBlockId, int currBlockId,
633	    llvm::SmallVector<DependencyInfo> &memoryDependencies,
634	    mlir::Operation *predOp, mlir::Operation *nextOp) {
635	  DependencyInfo depInfo;
636	
637	  if (predCoreType == ssbufferCoreTypeCubeAttr) {
638	    depInfo.type = DependencyType::CubeToVector;
639	  } else if (predCoreType == ssbufferCoreTypeVectorAttr) {
640	    depInfo.type = DependencyType::VectorToCube;
641	  }
642	  depInfo.producerBlockId = producerBlockId;
643	  depInfo.consumerBlockId = consumerBlockId;
644	  depInfo.iniProducerBlockId = predBlockId;
645	  depInfo.iniConsumerBlockId = currBlockId;
646	
647	  depInfo.predOp = predOp;
648	  depInfo.nextOp = nextOp;
649	
650	  memoryDependencies.push_back(depInfo);
651	}
652	
653	void DataDependencyAnalysisPass::analyzeMemoryEffect(DataDependencyInfo &info) {
654	  auto &memoryDependencies = info.getMemoryDependencies();
655	  LOG_DEBUG("\n=== start mem dep analysis ===\n");
656	
657	  auto &aliasAnalysis = getAnalysis<mlir::AliasAnalysis>();
658	  MemoryDependenceGraph memDepGraph(module, aliasAnalysis);
659	
660	  auto walkResult = module.walk([&](mlir::Operation *op) -> WalkResult {
661	    if (op->getNumRegions() > 0) {
662	      return WalkResult::advance();
663	    }
664	    if (isa<annotation::MarkOp, gpu::BarrierOp>(op)) {
665	      return WalkResult::advance();
666	    }
667	    auto currBlockIdOpt = CVPipeline::getOpBlockId(op);
668	    llvm::StringRef currCoreType = getSsbufferCoreType(op);
669	    if (!currBlockIdOpt || currCoreType.empty()) {
670	      return WalkResult::advance();
671	    }
672	    int currBlockId = *currBlockIdOpt;
673	
674	    for (mlir::Operation *predOp : memDepGraph.getExecBefore(op)) {
675	      if (isa<annotation::MarkOp, gpu::BarrierOp>(predOp)) {
676	        continue;
677	      }
678	      if (predOp->getNumRegions() > 0) {
679	        auto realdeps = memDepGraph.getRealDependency(predOp, op);
680	        if (realdeps.empty()) {
681	          return WalkResult::advance();
682	        }
683	        for (mlir::Operation *realPredOp : realdeps) {
684	          if (isa<annotation::MarkOp, gpu::BarrierOp>(realPredOp)) {
685	            continue;
686	          }
687	          auto realPredBlockIdOpt = CVPipeline::getOpBlockId(realPredOp);
688	          llvm::StringRef realPredCoreType = getSsbufferCoreType(realPredOp);
689	          if (!realPredBlockIdOpt || realPredCoreType == currCoreType ||
690	              realPredCoreType.empty()) {
691	            continue;
692	          }
693	          int realPredBlockId = static_cast<int>(*realPredBlockIdOpt);
694	          auto [producerBlockId, consumerBlockId] =
695	              findCommonLevelBlockIds(info, realPredBlockId, currBlockId);
696	          if (producerBlockId == -1 || consumerBlockId == -1) {
697	            LOG_DEBUG("Could not find common level block IDs for producer and "
698	                      "consumer blocks");
699	            return WalkResult::interrupt();
700	          }
701	          collectMemDepInfo(realPredCoreType, producerBlockId, consumerBlockId,
702	                            realPredBlockId, currBlockId, memoryDependencies,
703	                            realPredOp, op);
704	
705	          LOG_DEBUG("\n=op with region mem dep analysis= "
706	                    << "\nrealpredcoretype" << realPredCoreType
707	                    << "\nproducer Block: " << realPredBlockId
708	                    << "\nproducer Op: " << *realPredOp << "\nconsumer Block: "
709	                    << currBlockId << "\nconsumer Op: " << *op << "\n");
710	        }
711	        continue;
712	      }
713	      auto predBlockIdOpt = CVPipeline::getOpBlockId(predOp);
714	      llvm::StringRef predCoreType = getSsbufferCoreType(predOp);
715	      if (!predBlockIdOpt || predCoreType == currCoreType ||
716	          predCoreType.empty()) {
717	        continue;
718	      }
719	      int predBlockId = *predBlockIdOpt;
720	
721	      auto [producerBlockId, consumerBlockId] =
722	          findCommonLevelBlockIds(info, predBlockId, currBlockId);
723	      if (producerBlockId == -1 || consumerBlockId == -1) {
724	        LOG_DEBUG("Could not find common level block IDs for producer and "
725	                  "consumer blocks");
726	        return WalkResult::interrupt();
727	      }
728	      if (producerBlockId == consumerBlockId) {
729	        continue;
730	      }
731	
732	      collectMemDepInfo(predCoreType, producerBlockId, consumerBlockId,
733	                        predBlockId, currBlockId, memoryDependencies, predOp,
734	                        op);
735	
736	      LOG_DEBUG("\n=mem dep analysis= " << "\npredcoretype" << predCoreType
737	                                        << "\nproducer Block: " << predBlockId
738	                                        << "\nproducer Op: " << *predOp
739	                                        << "\nconsumer Block: " << currBlockId
740	                                        << "\nconsumer Op: " << *op << "\n");
741	    }
742	    return WalkResult::advance();
743	  });
744	  if (walkResult.wasInterrupted()) {
745	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
746	  }
747	  LOG_DEBUG("=== mem dep analysis complete ===\n");
748	}
749	
750	// Producer/Consumer Hierarchy Analysis
751	std::pair<int, int> DataDependencyAnalysisPass::findCommonLevelBlockIds(
752	    DataDependencyInfo &info, int producerBlockId, int consumerBlockId) {
753	  auto &blockInfoMap = info.getBlockInfoMap();
754	
755	  LOG_DEBUG("start findCommonLevelBlockIds...\n");
756	
757	  // Step 1: Get corresponding BlockInfo from Map
758	  auto pIt = blockInfoMap.find(producerBlockId);
759	  auto cIt = blockInfoMap.find(consumerBlockId);
760	  // Defensive programming: if corresponding Block info not found, return
761	  // original ID or error code
762	  if (pIt == blockInfoMap.end() || cIt == blockInfoMap.end()) {
763	    return {producerBlockId, consumerBlockId};
764	  }
765	
766	  BlockInfo &pInfo = pIt->second;
767	  BlockInfo &cInfo = cIt->second;
768	
769	  // Take the first operation of each Block as representative to check hierarchy
770	  // (Assumes all operations in a Block are closely related in hierarchy)
771	  mlir::Operation *producerOp = pInfo.Operations[0];
772	  mlir::Operation *consumerOp = cInfo.Operations[0];
773	
774	  mlir::Block *pBlock = producerOp->getBlock();
775	  mlir::Block *cBlock = consumerOp->getBlock();
776	
777	  // Case 1: In the same MLIR Block
778	  if (pBlock == cBlock) {
779	    return {producerBlockId, consumerBlockId};
780	  }
781	
782	  // Case 2: In different Blocks, find Lowest Common Ancestor (LCA)
783	  // Step 1: Collect producer's ancestor chain
784	  llvm::SmallVector<mlir::Operation *> pAncestors;
785	  pAncestors.push_back(producerOp);
786	  mlir::Operation *current = producerOp->getParentOp();
787	  while (current) {
788	    pAncestors.push_back(current);
789	    current = current->getParentOp();
790	  }
791	
792	  // Step 2: Walk up consumer's ancestors, using current and before for rolling
793	  mlir::Operation *before = consumerOp; // Initialize as consumerOp itself
794	  current = consumerOp;                 // Initialize as parent
795	
796	  while (current) {
797	    // --- Found common ancestor ---
798	    auto it = std::find(pAncestors.begin(), pAncestors.end(), current);
799	    if (it != pAncestors.end()) {
800	      size_t pIndex = std::distance(pAncestors.begin(), it);
801	      if (pIndex == 0) {
802	        break;
803	      }
804	      mlir::Operation *pPrevOp = pAncestors[pIndex - 1];
805	      auto pPrevIdOpt = CVPipeline::getOpBlockId(pPrevOp);
806	      auto cPrevIdOpt = CVPipeline::getOpBlockId(before);
807	      int pPrevId = pPrevIdOpt ? *pPrevIdOpt : -1;
808	      int cPrevId = cPrevIdOpt ? *cPrevIdOpt : -1;
809	      if (!pPrevIdOpt) {
810	        LOG_DEBUG("Warning: Producer ancestor operation has no block ID "
811	                  "attribute.\n");
812	      }
813	      if (!cPrevIdOpt) {
814	        LOG_DEBUG("Warning: Consumer ancestor operation has no block ID "
815	                  "attribute.\n");
816	      }
817	      return {pPrevId, cPrevId};
818	    }
819	
820	    // Rolling: continue upward
821	    before = current;
822	    current = current->getParentOp();
823	  }
824	  LOG_DEBUG("Warning: No common ancestor found for producer block "
825	            << producerBlockId << " and consumer block " << consumerBlockId
826	            << "\n");
827	  return {-1, -1};
828	}
829	
830	void DataDependencyAnalysisPass::runOnOperation() {
831	  LOG_DEBUG("\n--- enter DataDependencyAnalysisPass --->\n");
832	  module = getOperation();
833	
834	  if (CVPipeline::hasFallbackAttr(module)) {
835	    return;
836	  }
837	
838	  auto &info = getAnalysis<DataDependencyInfo>();
839	
840	  // Step 1: Collect block information (populate blockInfoMap)
841	  createBlockInfoMap(info);
842	
843	  // Step 2: Analyze iter_args dependencies
844	  processIterArgDependencies();
845	
846	  // Step 3: Analyze dependencies (populate v2c, c2v lists)
847	  analyzeExternalInputs(info);
848	
849	  analyzeExternalOutputs(info);
850	
851	  // Step 4: Analyze memory dependencies (memdep sync)
852	  analyzeMemoryEffect(info);
853	
854	  info.setValid(true);
855	
856	  LOG_DEBUG("DataDependencyAnalysisPass: Analysis complete.\n");
857	  LOG_DEBUG("  V->C dependencies: " << info.getV2CDependencies().size()
858	                                    << "\n");
859	  LOG_DEBUG("  C->V dependencies: " << info.getC2VDependencies().size()
860	                                    << "\n");
861	  LOG_DEBUG("  Memory dependencies: " << info.getMemoryDependencies().size()
862	                                      << "\n");
863	
864	  LOG_DEBUG("\n--- exit DataDependencyAnalysisPass --->\n");
865	}
866	
867	// Create the pass
868	namespace mlir {
869	namespace triton {
870	std::unique_ptr<OperationPass<ModuleOp>> createDataDependencyAnalysisPass() {
871	  return std::make_unique<DataDependencyAnalysisPass>();
872	}
873	
874	} // namespace triton
875	} // namespace mlir
