40	PropagateUnrealizedCastDown::PropagateUnrealizedCastDown(MLIRContext *context,
41	                                                         Value logicalBlockId,
42	                                                         Value logicalBlockNum,
43	                                                         int autoBlockifySize)
44	    : OpRewritePattern<UnrealizedConversionCastOp>(context),
45	      logicalBlockId(logicalBlockId), logicalBlockNum(logicalBlockNum),
46	      autoBlockifySize(autoBlockifySize) {}
47	
48	LogicalResult
49	PropagateUnrealizedCastDown::matchAndRewrite(UnrealizedConversionCastOp op,
50	                                             PatternRewriter &rewriter) const {
51	  if (op.getInputs().size() != 2)
52	    return failure();
53	  auto funcOp = op->getParentOfType<triton::FuncOp>();
54	  auto input = op.getInputs()[0];
55	  auto res = op->getResult(0);
56	  SmallPtrSet<Operation *, 8> users(op->user_begin(), op->user_end());
57	  LLVM_DEBUG({
58	    auto &os = llvm::dbgs();
59	    os << "Handling UnrealizedConversionCastOp:\n" << op << "\n";
60	    os << "Users:\n";
61	    for (auto *user : users)
62	      os << *user << "\n";
63	  });
64	  for (auto *user : users) {
65	    PatternRewriter::InsertionGuard guard(rewriter);
66	    rewriter.setInsertionPoint(user);
67	    if (auto uccOp = dyn_cast<UnrealizedConversionCastOp>(user)) {
68	      if (uccOp->getResultTypes()[0] != input.getType()) {
69	        LLVM_DEBUG({
70	          auto &os = llvm::dbgs();
71	          os << *user << "\n";
72	        });
73	        return op.emitError("UnrealizedConversionCastOp cannot be resolved\n");
74	      }
75	      rewriter.replaceOp(user, input);
76	    } else if (auto blockifyLoop = getBlockifyLoop(user)) {
77	      handleBlockifyLoop(blockifyLoop.value(), user, rewriter);
78	    } else if (auto splatOp = dyn_cast<triton::SplatOp>(user)) {
79	      rewriteSplat(op, splatOp, rewriter);
80	    } else if (auto expandDimsOp = dyn_cast<triton::ExpandDimsOp>(user)) {
81	      rewriteExpandDims(op, expandDimsOp, rewriter);
82	    } else if (auto reduceOp = dyn_cast<triton::ReduceOp>(user)) {
83	      rewriteReduce(op, reduceOp, rewriter);
84	    } else if (auto scanOp = dyn_cast<triton::ScanOp>(user)) {
85	      rewriteScan(op, scanOp, rewriter);
86	    } else if (auto loadOp = dyn_cast<triton::LoadOp>(user)) {
87	      rewriteLoad(op, loadOp, rewriter);
88	    } else if (auto storeOp = dyn_cast<triton::StoreOp>(user)) {
89	      rewriteStore(op, storeOp, rewriter);
90	    } else if (auto atomicRMWOp = dyn_cast<triton::AtomicRMWOp>(user)) {
91	      rewriteAtomicRMW(op, atomicRMWOp, rewriter);
92	    } else if (auto assertOp = dyn_cast<triton::AssertOp>(user)) {
93	      rewriteAssert(op, assertOp, rewriter);
94	    } else if (auto extractSliceOp = dyn_cast<tensor::ExtractSliceOp>(user)) {
95	      rewriteExtractSlice(op, extractSliceOp, rewriter);
96	    } else if (auto insertSliceOp = dyn_cast<tensor::InsertSliceOp>(user)) {
97	      rewriteInsertSlice(op, insertSliceOp, rewriter);
98	    } else if (auto whileOp = dyn_cast<scf::WhileOp>(user)) {
99	      rewriteWhile(op, whileOp, rewriter);
100	    } else if (auto loopOp = dyn_cast<LoopLikeOpInterface>(user)) {
101	      rewriteLoop(op, loopOp, rewriter);
102	    } else if (auto yieldOp = dyn_cast<scf::YieldOp>(user)) {
103	      rewriteYield(op, yieldOp, rewriter);
104	    } else if (auto conditionOp = dyn_cast<scf::ConditionOp>(user)) {
105	      rewriteCondition(op, conditionOp, rewriter);
106	    } else if (user->hasTrait<OpTrait::Elementwise>() ||
107	               isa<triton::BroadcastOp, triton::JoinOp, triton::ReshapeOp,
108	                   triton::PrintOp, triton::ascend::AnnotationOp>(user)) {
109	      rewriteGeneraleOp(op, user, rewriter);
110	    } else if (isa<triton::AtomicCASOp>(user)) {
111	      auto *newOp =
112	          createBlockifyLoop(user, op, logicalBlockId, logicalBlockNum,
113	                             autoBlockifySize, rewriter);
114	      rewriter.setInsertionPoint(newOp);
115	      handleBlockifyLoop(*getBlockifyLoop(newOp), newOp, rewriter);
116	    } else {
117	      LLVM_DEBUG({
118	        auto &os = llvm::dbgs();
119	        os << "Unhandled Op\n" << *user << "\n";
120	      });
121	      llvm_unreachable("Unhandled operation");
122	    }
123	  }
124	  LLVM_DEBUG({
125	    auto &os = llvm::dbgs();
126	    os << "After successful conversion\n";
127	    os << funcOp << "\n";
128	  });
129	  rewriter.eraseOp(op);
130	  return success();
131	}
