135	
136	bool AutoBlockifyPass::checkBlockifiable(Value v) {
137	  if (!checkedValues.insert(v).second)
138	    return true;
139	  LLVM_DEBUG({
140	    auto &os = llvm::dbgs();
141	    os << "Checking blockifiable:\n" << v << "\n";
142	  });
143	  for (auto &use : v.getUses()) {
144	    auto *user = use.getOwner();
145	    auto opNum = use.getOperandNumber();
146	    LLVM_DEBUG({
147	      auto &os = llvm::dbgs();
148	      os << "User:\n" << *user << "\n";
149	    });
150	    if (isa<cf::CondBranchOp, triton::IntToPtrOp, scf::WhileOp, triton::DotOp>(
151	            user) ||
152	        llvm::any_of(user->getOperandTypes(), isTensorPtrType))
153	      return false;
154	    if (auto ifOp = dyn_cast<scf::IfOp>(user)) {
155	      user->setAttr(autoBlockifyRegionOpAttr, UnitAttr::get(v.getContext()));
156	      return true;
157	    } else if (auto whileOp = dyn_cast<scf::WhileOp>(user)) {
158	      if (!checkBlockifiable(whileOp.getBeforeArguments()[opNum]))
159	        return false;
160	    } else if (auto loopOp = dyn_cast<LoopLikeOpInterface>(user)) {
161	      auto regionIterArg = loopOp.getTiedLoopRegionIterArg(&use);
162	      auto loopResult = loopOp.getTiedLoopResult(&use);
163	      if (!regionIterArg || !loopResult) {
164	        user->setAttr(autoBlockifyRegionOpAttr, UnitAttr::get(v.getContext()));
165	        return true;
166	      }
167	      if (!checkBlockifiable(regionIterArg) || !checkBlockifiable(loopResult))
168	        return false;
169	    } else if (auto conditionOp = dyn_cast<scf::ConditionOp>(user)) {
170	      auto whileOp = cast<scf::WhileOp>(user->getParentOp());
171	      if (opNum == 0) {
172	        whileOp->setAttr(autoBlockifyRegionOpAttr,
173	                         UnitAttr::get(v.getContext()));
174	        return true;
175	      }
176	      if (!checkBlockifiable(whileOp.getAfterArguments()[opNum - 1]) ||
177	          !checkBlockifiable(whileOp->getResult(opNum - 1)))
178	        return false;
179	    } else if (auto conditionOp = dyn_cast<scf::YieldOp>(user)) {
180	      if (auto loopOp = dyn_cast<LoopLikeOpInterface>(user->getParentOp());
181	          loopOp && !checkBlockifiable(loopOp.getInits()[opNum]))
182	        return false;
183	    } else {
184	      for (auto res : user->getResults()) {
185	        if (!checkBlockifiable(res))
186	          return false;
187	      }
188	    }
189	  }
190	  return true;
191	}
192	
193	void AutoBlockifyPass::preProcess(triton::FuncOp func) {
194	  IRRewriter rewriter(func.getContext());
195	  rewriter.setInsertionPointToStart(&func.getBody().front());
196	  auto loc = rewriter.getUnknownLoc();
197	  // Get logical block num
198	  auto xNum =
199	      rewriter.create<triton::GetNumProgramsOp>(loc, triton::ProgramIDDim::X);
200	  auto yNum =
201	      rewriter.create<triton::GetNumProgramsOp>(loc, triton::ProgramIDDim::Y);
202	  auto zNum =
203	      rewriter.create<triton::GetNumProgramsOp>(loc, triton::ProgramIDDim::Z);
204	  auto yzNum = rewriter.create<arith::MulIOp>(loc, yNum, zNum);
205	  logicalBlockNum = rewriter.create<arith::MulIOp>(loc, yzNum, xNum);
206	
207	  // Get logical block id
208	  auto xDim =
209	      rewriter.create<triton::GetProgramIdOp>(loc, triton::ProgramIDDim::X);
210	  auto yDim =
211	      rewriter.create<triton::GetProgramIdOp>(loc, triton::ProgramIDDim::Y);
212	  auto zDim =
213	      rewriter.create<triton::GetProgramIdOp>(loc, triton::ProgramIDDim::Z);
214	  xDim->setAttr(logicalBlockIdAttr, rewriter.getUnitAttr());
215	  yDim->setAttr(logicalBlockIdAttr, rewriter.getUnitAttr());
216	  zDim->setAttr(logicalBlockIdAttr, rewriter.getUnitAttr());
217	  auto xFlatten = rewriter.create<arith::MulIOp>(loc, xDim, yzNum);
218	  auto yFlatten = rewriter.create<arith::MulIOp>(loc, yDim, zNum);
219	  logicalBlockId = rewriter.create<arith::AddIOp>(loc, xFlatten, yFlatten);
220	  logicalBlockId = rewriter.create<arith::AddIOp>(loc, logicalBlockId, zDim);
221	
222	  // get blockified block id
223	  auto blockifyTensorType =
224	      RankedTensorType::get({autoBlockifySize}, rewriter.getI32Type());
225	  auto blockfyRange = rewriter.create<triton::MakeRangeOp>(
226	      loc, blockifyTensorType, 0, autoBlockifySize);
227	  auto splatedLogicalBlockId = rewriter.create<triton::SplatOp>(
228	      loc, blockfyRange.getType(), logicalBlockId);
229	  Value blockifiedId =
230	      rewriter.create<arith::AddIOp>(loc, splatedLogicalBlockId, blockfyRange);
231	
232	  // get mask
233	  auto splatedBlockNum = rewriter.create<triton::SplatOp>(
234	      loc, blockfyRange.getType(), logicalBlockNum);
235	  auto upperboundMask = rewriter.create<arith::CmpIOp>(
236	      loc, arith::CmpIPredicate::slt, blockifiedId, splatedBlockNum);
237	  auto splatedZero = rewriter.create<arith::ConstantOp>(
238	      loc, DenseElementsAttr::get(blockifyTensorType,
239	                                  rewriter.getI32IntegerAttr(0)));
240	  auto lowerboundMask = rewriter.create<arith::CmpIOp>(
241	      loc, arith::CmpIPredicate::sge, blockifiedId, splatedZero);
242	  Value blockifiedIdMask =
243	      rewriter.create<arith::OrIOp>(loc, upperboundMask, lowerboundMask);
244	
245	  blockifiedId = rewriter
246	                     .create<UnrealizedConversionCastOp>(
247	                         loc, logicalBlockId.getType(),
248	                         ValueRange({blockifiedId, blockifiedIdMask}))
249	                     ->getResult(0);
250	
251	  // replace program id to be computed from blockified id
252	  SmallVector<triton::GetProgramIdOp> toReplace;
253	  func.walk([&](triton::GetProgramIdOp id) {
254	    if (id->hasAttr(logicalBlockIdAttr))
255	      return;
256	    toReplace.push_back(id);
257	  });
258	  for (auto id : toReplace) {
259	    rewriter.setInsertionPoint(id);
260	    Value newId;
261	    if (id.getAxis() == triton::ProgramIDDim::X) {
262	      newId = rewriter.create<arith::DivSIOp>(id.getLoc(), blockifiedId, yzNum);
263	      newId = rewriter.create<arith::RemSIOp>(id.getLoc(), newId, xNum);
264	    } else if (id.getAxis() == triton::ProgramIDDim::Y) {
265	      newId = rewriter.create<arith::DivSIOp>(id.getLoc(), blockifiedId, zNum);
266	      newId = rewriter.create<arith::RemSIOp>(id.getLoc(), newId, yNum);
267	    } else {
268	      newId = rewriter.create<arith::RemSIOp>(id.getLoc(), blockifiedId, zNum);
269	    }
270	    rewriter.replaceOp(id, newId);
271	  }
272	
273	  // Create for loop for region ops
274	  func.walk<WalkOrder::PreOrder>([&](Operation *op) {
275	    if (op->hasAttr(autoBlockifyRegionOpAttr)) {
276	      auto *newOp = createBlockifyLoop(
277	          op, blockifiedId.getDefiningOp<UnrealizedConversionCastOp>(),
278	          logicalBlockId, logicalBlockNum, autoBlockifySize, rewriter);
279	      newOp->removeAttr(autoBlockifyRegionOpAttr);
280	      return WalkResult::skip();
281	    }
282	    return WalkResult::advance();
283	  });
284	}
285	
286	void AutoBlockifyPass::runOnOperation() {
287	  if (autoBlockifySize == 1)
288	    return;
289	  ModuleOp moduleOp = getOperation();
290	  if (autoBlockifySize <= 0) {
291	    moduleOp->emitWarning("[AutoBlockify V2] AutoBlockifySize cannot be "
292	                          "negative integer, skipping.");
293	    return signalPassFailure();
294	  }
295	
296	  MLIRContext *ctx = &getContext();
297	
298	  moduleOp.walk([&](triton::FuncOp func) {
299	    LogicalResult result = success();
300	    func.walk([&](triton::GetProgramIdOp id) {
301	      if (!checkBlockifiable(id.getResult())) {
302	        result = failure();
303	        return WalkResult::interrupt();
304	      }
305	      return WalkResult::advance();
306	    });
307	    if (failed(result)) {
308	      func->emitWarning("Cannot apply auto blockify");
309	      return WalkResult::skip();
310	    }
311	    preProcess(func);
312	
313	    LLVM_DEBUG({
314	      auto &os = llvm::dbgs();
315	      os << "After preprocess:\n" << func << "\n";
316	    });
317	
318	    RewritePatternSet patterns(ctx);
319	    patterns.add<PropagateUnrealizedCastDown>(
320	        ctx, logicalBlockId, logicalBlockNum, autoBlockifySize);
321	
322	    if (failed(applyPatternsGreedily(func, std::move(patterns)))) {
323	      moduleOp->emitError("failed to apply Patterns");
324	      signalPassFailure();
325	      return WalkResult::interrupt();
326	    }
327	
328	    IRRewriter rewriter(ctx);
329	    func->walk([&](UnrealizedConversionCastOp op) {
330	      rewriter.setInsertionPoint(op);
331	      auto input = op.getInputs()[0];
332	      auto resType = cast<RankedTensorType>(op->getResultTypes()[0]);
333	      if (auto constantOp = input.getDefiningOp<arith::ConstantOp>()) {
334	        Attribute val = constantOp.getValue();
335	        if (auto denseAttr = dyn_cast<DenseElementsAttr>(val))
336	          val = denseAttr.getSplatValue<Attribute>();
337	        rewriter.replaceOpWithNewOp<arith::ConstantOp>(
338	            op, DenseElementsAttr::get(resType, val));
339	      } else if (auto tensorType =
340	                     dyn_cast<RankedTensorType>(input.getType())) {
341	        input = rewriter.create<triton::ExpandDimsOp>(input.getLoc(), input, 0);
342	        rewriter.replaceOpWithNewOp<triton::BroadcastOp>(op, resType, input);
343	      } else {
344	        rewriter.replaceOpWithNewOp<triton::SplatOp>(op, resType, input);
345	      }
346	    });
347	    func->setAttr(autoBlockifySizeAttr,
348	                  rewriter.getI32IntegerAttr(autoBlockifySize));
349	    return WalkResult::skip();
350	  });
351	
352	  PassManager pm(&getContext(), moduleOp.getOperationName());
353	  pm.addPass(createCSEPass());
354	  pm.addPass(createCanonicalizerPass());
355	  if (failed(runPipeline(pm, moduleOp))) {
356	    signalPassFailure();
357	  }
358	}
359	
360	std::unique_ptr<OperationPass<ModuleOp>>
361	triton::createAutoBlockifyPass(const AutoBlockifyOptions &options) {
362	  return std::make_unique<AutoBlockifyPass>(options);
363	}
